#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;
    long long m = (long long)n * (n - 1) / 2;
    vector<vector<long long>> dp(n + 1, vector<long long>(n * (n - 1) + 1, 0));
    vector<vector<long long>> dp1(n + 1, vector<long long>(n * (n - 1) + 1, 0));
    dp[1][m] = 1;
    for (int i = 2; i <= n; ++i) {
        int lower_bound = m - (i - 1) * (i - 2) / 2;
        int upper_bound = m + (i - 1) * (i - 2) / 2;
        for (int x = lower_bound; x <= upper_bound; ++x) {
            for (int d = -i + 1; d < i; ++d) {
                int idx = x + d;
                if (idx >= 0 && idx <= n * (n - 1))
                    dp[i][idx] = (dp[i][idx] + dp[i - 1][x] * (i - abs(d))) % mod;
            }
        }
        for (int x = lower_bound; x <= upper_bound; ++x) {
            dp1[i][x] = (dp1[i - 1][x] * i) % mod;
        }
        for (int x = lower_bound; x <= upper_bound; ++x) {
            for (int d = 1; d < i; ++d) {
                int idx = x - d;
                if (idx >= 0 && idx <= n * (n - 1))
                    dp1[i][idx] = (dp1[i][idx] + dp[i - 1][x] * (i - d)) % mod;
            }
        }
    }
    long long result = 0;
    int lower_bound = m + 1;
    int upper_bound = m + (n - 1) * (n - 2) / 2;
    for (int x = lower_bound; x <= upper_bound; ++x) {
        result = (result + dp1[n][x]) % mod;
    }
    cout << result << "\n";
    return 0;
}
